// Team-project landmarks (built by an office together, see backend/src/village/extras.ts).
// Generated by scripts/make-landmarks.py. Only offices that built one can place it (checked on save).
import { SpriteSheetTile } from './spritesheet'
import { SpriteSheetData } from './SpriteSheetData'

const width = 512
const height = 128
const url = '/sprites/spritesheets/landmarks.png'

const all = (w: number, h: number) => Array.from({ length: w * h }, (_, i) => ({ x: i % w, y: Math.floor(i / w) }))

const sprites: SpriteSheetTile[] = [
    // the deck is walkable; only the open water beside it blocks
    { name: 'bridge', x: 0, y: 0, width: 128, height: 96, layer: 'object', colliders: [{ x: 0, y: 1 }, { x: 3, y: 1 }] },
    { name: 'fountain', x: 128, y: 0, width: 128, height: 128, layer: 'object', colliders: all(4, 4) },
    { name: 'well', x: 256, y: 0, width: 64, height: 96, layer: 'object', colliders: [{ x: 0, y: 1 }, { x: 1, y: 1 }, { x: 0, y: 2 }, { x: 1, y: 2 }] },
]

/** Landmarks this office has built (set by the editor page from the server). Locked ones can't be placed. */
export const editorLandmarks: { unlocked: string[] } = { unlocked: [] }

/** Landmark sprite → team project id. */
export const LANDMARK_PROJECT: Record<string, string> = { bridge: 'bridge', fountain: 'fountain', well: 'well' }

const landmarksSpriteSheetData = new SpriteSheetData(width, height, url, sprites)

export { landmarksSpriteSheetData }
